function buildCodeBlock(def, values) {
  const language = def.language ?? def.id ?? "";
  if (def.template) {
    let result = "```" + language + "\n" + def.template + "\n```\n";
    for (const [key, val] of Object.entries(values)) {
      if (val && val.trim() !== "") {
        result = result.replace(new RegExp(`\\{\\{${key}\\}\\}`, "g"), val.trim());
      }
    }
    result = result.replace(/\{\{[^}]+\}\}/g, "");
    return result;
  }
  const lines = [language];
  for (const p of def.params) {
    const v = values[p.key];
    if (v === void 0 || v === null)
      continue;
    const trimmed = v.trim();
    if (trimmed === "")
      continue;
    lines.push(`${p.key}: ${trimmed}`);
  }
  return "```" + lines.join("\n") + "\n```\n";
}

// src/cli/commands/blockCmd.ts
async function cmdBlock(env, args) {
  const defId = args.positional[0];
  if (!defId) {
    throw new UsageError(
      `\u7528\u6CD5\uFF1Aworkout-cli block <${CODE_BLOCK_DEFS.map((d) => d.id).join("|")}> [--param key=value ...]`
    );
  }
  const def = CODE_BLOCK_DEFS.find((d) => d.id === defId);
  if (!def) {
    throw new CliError(`\u672A\u77E5\u4EE3\u7801\u5757 "${defId}"\u3002\u53EF\u9009\uFF1A${CODE_BLOCK_DEFS.map((d) => d.id).join("\u3001")}`);
  }
  const values = {};
  const validKeys = new Set(def.params.map((p) => p.key));
  for (const kv of args.repeated["param"] ?? []) {
    const eq = kv.indexOf("=");
    if (eq <= 0)
      throw new UsageError(`--param \u9700\u8981 key=value \u5F62\u5F0F\uFF0C\u6536\u5230\uFF1A"${kv}"`);
    const key = kv.slice(0, eq);
    if (!validKeys.has(key)) {
      throw new CliError(
        `\u4EE3\u7801\u5757 ${def.id} \u6CA1\u6709\u53C2\u6570 "${key}"\uFF08\u5199\u9519\u7684\u53C2\u6570\u4F1A\u88AB\u89E3\u6790\u5668\u9759\u9ED8\u5FFD\u7565\uFF09\u3002\u53EF\u7528\u53C2\u6570\uFF1A${Array.from(validKeys).join(", ")}`
      );
    }
    values[key] = kv.slice(eq + 1);
  }
  if (values["exercise"]) {
    const exercise = resolveExerciseByName(env.config, values["exercise"]);
    if (exercise)
      values["exercise"] = getExerciseName(exercise);
  }
  process.stdout.write(buildCodeBlock(def, values));
}

